CREATE TABLE IF NOT EXISTS user_roles(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('student','recruiter','college','reviewer')), granted_by uuid REFERENCES users ON DELETE SET NULL, granted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role));
CREATE TABLE IF NOT EXISTS reassessment_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), passport_id uuid NOT NULL REFERENCES passports ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, recruiter_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, challenge_id text NOT NULL, challenge_version text NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','completed','expired')), assessment_id uuid REFERENCES assessments ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz, FOREIGN KEY(challenge_id,challenge_version) REFERENCES challenges(id,version));
CREATE TABLE IF NOT EXISTS repository_provenance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, repository_id uuid NOT NULL REFERENCES repositories ON DELETE CASCADE, commit_sha text NOT NULL, commit_url text NOT NULL, author_login text, author_verified boolean NOT NULL DEFAULT false, uncertainty text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(repository_id,commit_sha));
ALTER TABLE repositories ADD COLUMN IF NOT EXISTS is_fork boolean NOT NULL DEFAULT false;
ALTER TABLE repositories ADD COLUMN IF NOT EXISTS parent_full_name text;
CREATE INDEX IF NOT EXISTS reassessment_candidate_status ON reassessment_requests(candidate_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS repository_provenance_user_repo ON repository_provenance(user_id,repository_id,observed_at DESC);
